# Intermediate unit 51 – Feelings. Bám sách: trang 106–107 (đã xem ảnh trang) + đáp án + Mini dictionary. Không chép nguyên văn.
# Nghĩa mới của headword cũ → sense: brighten up (người), calm down (người), break down (khóc), take to (thích). jump at (có định nghĩa trên trang) làm thẻ.
theory = (
 H("A", "Feelings go up and down", "Cảm xúc lên và xuống")
 + P("With feelings, <i>up</i> often refers to positive emotions or greater intensity, and <i>down</i> to negative ones or less intensity.", "Với cảm xúc, <i>up</i> thường chỉ cảm xúc tích cực hoặc mạnh hơn, <i>down</i> chỉ cảm xúc tiêu cực hoặc dịu đi.")
 + T([
   ("brighten up", "suddenly look or feel happier – ‘You’re depressing everyone!’", "bỗng tươi tỉnh lên – ‘Cậu làm mọi người buồn theo!’"),
   ("cheer sb up", "make someone start to feel happier – a film", "làm ai vui lên – một bộ phim"),
   ("be hung up (about sth)", "be very worried and keep thinking about it (informal)", "lo lắng day dứt mãi (thân mật)"),
   ("break down", "be unable to control your feelings and start to cry – bad news", "không kìm được mà òa khóc – tin dữ"),
   ("calm down", "stop feeling angry, upset or excited – losing your temper won’t help", "bình tĩnh lại – nổi nóng chẳng giải quyết gì"),
   ("cool down", "become calmer – before seeing him again", "nguôi giận – trước khi gặp lại anh ta"),
 ])
 + H("B", "More verbs connected with feelings", "Thêm động từ về cảm xúc")
 + P("Advice emails: don’t <b>bottle up</b> your anger (hide it) or you may <b>tear yourself apart</b> (make yourself very unhappy). Don’t get <b>carried away</b> (so excited you lose control); <b>jump at</b> the chance of a new challenge (eagerly accept it). At first you may not want to join Kian’s activity holiday, but you may <b>warm to</b> it (become more enthusiastic) – it could <b>grow on</b> you (you like it more and more) and you may find yourself <b>taking to</b> it (starting to like it). You <b>feel for</b> Poppy (feel sorry for her), but she has lots of <b>hang-ups</b> (fears or embarrassments) and must <b>pull herself together</b> (become calm and sensible).",
     "Các email khuyên nhủ: đừng <b>bottle up</b> cơn giận (kìm nén) kẻo <b>tear yourself apart</b> (tự làm mình khổ). Đừng <b>carried away</b> (quá đà); hãy <b>jump at</b> cơ hội thử thách mới (chớp lấy). Ban đầu có thể không muốn tham gia kỳ nghỉ hoạt động Kian gợi ý, nhưng bạn có thể <b>warm to</b> nó (hào hứng dần) – nó sẽ <b>grow on</b> bạn (càng lúc càng thích) và bạn sẽ <b>taking to</b> nó (bắt đầu mê). Bạn <b>feel for</b> Poppy (thương cảm), nhưng cô ấy có nhiều <b>hang-ups</b> (mặc cảm, nỗi sợ) và phải <b>pull herself together</b> (trấn tĩnh lại).")
)
